async registerEmployeeInRepository(repository, options, sourceSettings) {
    const current = (await repository.findOne({
        filter: { username: options.username },
    })) ?? undefined;
    const value = this.toBuiltInEmployee(options, current);
    // Registration refreshes legacy arrays, never an administrator's override.
    for (const key of ['enabledSkills', 'enabledTools']) {
        const selection = current?.skillSettings?.[key] !== undefined
            ? current.skillSettings[key]
            : sourceSettings?.[key];
        if (selection !== undefined) {
            value.skillSettings[key] =
                selection === null ? null : [...new Set(selection)];
        }
    }
    if (Array.isArray(value.skillSettings.enabledTools)) {
        // The manager cannot classify dynamic tools by scope. Keep all saved
        // settings; runtime only consults these permissions for CUSTOM tools.
        // Saved ASK must win over a subsequently registered ALLOW default.
        value.skillSettings.tools = [
            ...new Map([
                ...value.skillSettings.tools,
                ...(sourceSettings?.tools ?? []),
                ...(current?.skillSettings?.tools ?? []),
            ].map((tool) => [tool.name, tool])).values(),
        ];
    }
    // Approval overrides are independent of selection overrides. Legacy
    // employees still inherit the registered tool list, but not new approval
    // defaults for names whose permissions have already been saved.
    const savedTools = new Map([
        ...(sourceSettings?.tools ?? []),
        ...(current?.skillSettings?.tools ?? []),
    ].map((tool) => [tool.name, tool]));
    value.skillSettings.tools = value.skillSettings.tools.map((tool) => {
        const saved = savedTools.get(tool.name);
        return typeof saved?.autoCall === 'boolean'
            ? { ...tool, autoCall: saved.autoCall }
            : tool;
    });
    if (current) {
        await repository.update({
            filter: { username: options.username },
            values: value,
        });
        return;
    }
    await repository.create({ values: value });
}

/** Explicit lifecycle contract for application-owned AI resources. */
export class AIResourceRegistrar {
    logger;
    skillsDirectories;
    constructor(options = {}) {
        this.logger = options.logger;
        this.skillsDirectories = normalizeDirectories(options.skillsDirectories ?? [], options.source ?? 'application');
    }
    async registerAIResources(ai) {
        await this.registerTools(ai.toolsManager);
        this.logStage('tools', await ai.toolsManager.listTools({}));
        await this.loadSkills(ai);
        this.logStage('skills', await ai.skillsManager.listSkills());
        await this.registerAIEmployees(ai.employeeManager);
        this.logStage('employees', await ai.employeeManager.listEmployees());
    }
    async loadSkills(ai) {
        for (const { directory, source, optional } of this.skillsDirectories) {
            if (!fs.existsSync(directory)) {
                this.logger?.[optional ? 'debug' : 'warn']?.({ directory, source, stage: 'skills' }, 'AI Skill directory does not exist; skipping');
                continue;
            }
            await new SkillsLoader(ai, {
                scan: {
                    basePath: directory,
                    pattern: ['**/SKILL.md'],
                },
                logger: this.logger,
            }).load();
            this.logger?.debug?.({ directory, source, stage: 'skills' }, 'AI Skill directory loaded');
        }
    }
    logStage(stage, resources) {
        this.logger?.debug?.({ total: resources.length, stage }, `AI ${stage} registration completed`);
    }
}

